function showPin(){state.pin='';state.app='pin';setView(`<div class="passcode"><span class="pin-lock"><svg class="icon-svg" viewBox="0 0 24 24"><path d="M7 10V7a5 5 0 0 1 10 0v3"/><rect x="5" y="10" width="14" height="12" rx="2" fill="currentColor" stroke="none"/></svg></span><h2>输入密码</h2><div class="dots">${'<i></i>'.repeat(6)}</div><p class="pin-error" id="pin-error"></p><div class="keypad">${[1,2,3,4,5,6,7,8,9,'',0].map((x,i)=>x===''?'<span></span>':`<button onclick="pinKey('${x}')" aria-label="数字${x}">${x}<small>${['','ABC','DEF','GHI','JKL','MNO','PQRS','TUV','WXYZ','',''][i]}</small></button>`).join('')}<span></span></div><div class="pass-footer"><button onclick="toast('本模拟手机不拨打真实电话')">紧急情况</button><button id="pin-cancel-delete" onclick="pinFooterAction()">取消</button></div></div>`,true)}
