function openApp(id){if(!state.unlocked)return;if(state.callNumber)return;if(state.ftActive)endFaceTime(false);state.app=id;switch(id){case'home':renderHome();break;case'facetime':renderFaceTime();break;case'music':renderMusic();break;case'photos':renderPhotos();break;case'kakao':renderKakao();break;case'instagram':renderIG();break;case'x':state.xVisited=true;renderX();break;case'calendar':renderCalendar();break;case'notes':renderNotes();break;case'reminders':renderReminders();break;case'phone':renderPhone();break;case'weather':renderWeather();break;case'map':renderMap();break;case'settings':renderSettings();break;case'clock':renderClock();break;case'social':case'tools':renderFolder(id);break;case'browser':renderBrowser();break;case'camera':renderCamera();break;case'mail':case'messages':renderInbox(id);break;case'store':renderStore();break;default:renderHome()}}
function renderFolder(id){setView(`<div class="homescreen"><div class="folder-page"><h2>${appNames[id]}</h2><div class="apps">${(id==='social'?['x','instagram','kakao']:['clock','notes','reminders','settings']).map(tile).join('')}</div></div></div>`,true)}
function formatTime(s){if(!Number.isFinite(s))return'0:00';return Math.floor(s/60)+':'+String(Math.floor(s%60)).padStart(2,'0')}
function renderMusic(){setView(page(`<div class="music-drag"><button onclick="musicLibrary()" aria-label="收起播放器"></button></div><div class="music-content"><div class="cover-wrap">${img(4,'album-cover','YOU LIKE IT I LOVE IT 专辑封面')}</div><div class="track"><div><h2>YOU LIKE IT I LOVE IT</h2><p>TWS / 24kGoldn</p></div><div class="track-actions"><button onclick="this.classList.toggle('liked')" aria-label="收藏歌曲">☆</button><button onclick="musicLibrary()" aria-label="更多音乐选项">···</button></div></div><div class="music-scrubber"><input class="music-range" id="music-seek" aria-label="音乐进度" type="range" min="0" max="${music.duration||181.56}" step=".1" value="${music.currentTime}" oninput="music.currentTime=Number(this.value)"><div class="time-row"><span id="elapsed">${formatTime(music.currentTime)}</span><span id="remaining">-${formatTime((music.duration||181.56)-music.currentTime)}</span></div></div><div class="transport"><button onclick="music.currentTime=0" aria-label="从头播放">${icon('prev')}</button><button class="play" id="music-play" onclick="toggleMusic()" aria-label="${music.paused?'播放音乐':'暂停音乐'}">${icon(music.paused?'play':'pause')}</button><button onclick="music.currentTime=0" aria-label="下一首">${icon('next')}</button></div><div class="volume"><svg class="icon-svg" viewBox="0 0 24 24"><path d="M3 9h4l5-5v16l-5-5H3z" fill="currentColor" stroke="none"/></svg><input type="range" min="0" max="1" step=".01" value="${music.volume}" aria-label="音乐音量" oninput="music.volume=Number(this.value)">${icon('volume')}</div><div class="music-bottom"><button onclick="toast('暂无歌词')" aria-label="歌词">${icon('chat')}</button><button onclick="toast('通过当前设备播放')" aria-label="播放设备"><svg class="icon-svg" viewBox="0 0 24 24"><path d="m8 21 4-6 4 6zM5 15a9 9 0 1 1 14 0M8 12a5 5 0 1 1 8 0"/></svg></button><button onclick="musicLibrary()" aria-label="播放列表">${icon('list')}</button></div></div>`,'music-page'),true);updateMusicUI()}
async function toggleMusic(){if(!music.paused)music.pause();else await playSafe(music);updateMusicUI()}

function updateMusicUI(){if($('#music-play')){$('#music-play').innerHTML=icon(music.paused?'play':'pause');$('#music-play').setAttribute('aria-label',music.paused?'播放音乐':'暂停音乐')}if($('#music-seek')){$('#music-seek').max=music.duration||181.56;$('#music-seek').value=music.currentTime;$('#elapsed').textContent=formatTime(music.currentTime);$('#remaining').textContent='-'+formatTime((music.duration||181.56)-music.currentTime)}}
music.addEventListener('timeupdate',updateMusicUI);music.addEventListener('pause',updateMusicUI);music.addEventListener('play',updateMusicUI);
function musicLibrary(){setView(page(header('音乐','','renderMusic()')+`<h1 class="large-title">资料库</h1><div class="list"><button class="list-row" onclick="renderMusic()">${img(4,'avatar')}<span class="grow"><strong>YOU LIKE IT I LOVE IT</strong><p>TWS / 24kGoldn</p></span>›</button></div>`))}
function renderPhotos(album=state.album){state.album=album;state.app='photos';setView(page(header(album==='hidden'?'已隐藏':'照片',`<button class="text-action" onclick="renderPhotos('${album==='hidden'?'public':'hidden'}')">${album==='hidden'?'公开相册':'已隐藏'}</button>`)+`<div class="scroll">${album==='hidden'&&!state.hiddenUnlocked?`<form class="hidden-form" onsubmit="unlockHidden(event)"><h2>已隐藏的相册</h2><p class="muted">输入四位密码查看</p><input aria-label="隐藏相册密码" id="hidden-pin" inputmode="numeric" maxlength="4" type="password" autocomplete="off"><br><button class="primary" type="submit">解锁相册</button><p class="muted" id="hidden-error"></p></form>`:`<p class="muted" style="margin:0 18px 15px">${album==='public'?publicPhotoList().length:hiddenPhotos.length} 张照片 · 随机排列</p><div class="photo-grid">${(album==='public'?publicPhotoList():hiddenPhotos).map((n,i)=>`<button onclick="showPhoto(${i})" aria-label="查看照片${n}">${img(n)}</button>`).join('')}</div>`}</div>`))}
function unlockHidden(e){e.preventDefault();if($('#hidden-pin').value==='0531'){state.hiddenUnlocked=true;renderPhotos('hidden')}else $('#hidden-error').textContent='密码不正确，请重试。'}
function showPhoto(i){state.photoIndex=i;let arr=state.album==='hidden'?hiddenPhotos:publicPhotoList();$('.photo-view')?.remove();let el=document.createElement('div');el.className='photo-view';el.innerHTML=header(`${i+1} / ${arr.length}`,'','closePhoto()')+img(arr[i],'full-photo','完整原图')+`<div class="photo-strip">${arr.map((n,j)=>`<button onclick="showPhoto(${j})" aria-label="切换照片${j+1}">${img(n)}</button>`).join('')}</div><div class="photo-actions"><button onclick="showPhoto((${i}+${arr.length}-1)%${arr.length})" aria-label="上一张">‹</button><button onclick="this.classList.toggle('liked');this.setAttribute('aria-pressed',this.classList.contains('liked'))" aria-label="喜欢照片" aria-pressed="false">${icon('heart')}</button><button onclick="showPhoto((${i}+1)%${arr.length})" aria-label="下一张">›</button></div>`;$('#screen').append(el);$('#screen').classList.add('light-text');el.addEventListener('touchstart',e=>{el.dataset.touchStart=e.touches[0].clientX},{passive:true});el.addEventListener('touchend',e=>{let dx=e.changedTouches[0].clientX-Number(el.dataset.touchStart);if(Math.abs(dx)>60)showPhoto((i+(dx<0?1:arr.length-1))%arr.length)},{passive:true})}
function closePhoto(){$('.photo-view')?.remove();$('#screen').classList.remove('light-text')}
function igBottom(tab){const items=[['home','首页','home'],['search','搜索','search'],['create','创建','plus'],['reels','Reels','camera'],['profile','主页','user']];return `<nav class="tabbar ig-tabbar">${items.map(([id,label,ic])=>`<button aria-label="Instagram${label}" class="${id===tab?'active':''}" onclick="renderIG('${id}')">${id==='profile'?'<img src="assets/ig-shinyu-avatar.jpg" class="ig-tab-avatar" alt="个人头像">':icon(ic)}</button>`).join('')}</nav>`}
function renderIG(tab=state.igTab){if(state.storyAvailable)$('#notification').innerHTML='';state.igTab=tab;state.app='instagram';let content='',head='';
if(tab==='home'){head=`<div class="ig-top"><span class="ig-logo">Instagram</span><div><button onclick="renderIG('activity')" aria-label="Instagram动态">${icon('heart')}</button><button onclick="renderIG('dm')" aria-label="Instagram私信">${icon('send')}</button></div></div>`;content=`<div class="stories"><button onclick="toast('暂无快拍')"><div class="story-ring own-story"><img src="assets/ig-shinyu-avatar.jpg" alt="个人头像"><i>＋</i></div><p>你的快拍</p></button><button onclick="showIGStory()" aria-label="${state.storyViewed?'重看英宰快拍':'查看英宰快拍'}"><div class="story-ring ${!state.storyAvailable?'story-unavailable':state.storyViewed?'story-seen':'story-unread'}">${img(3)}</div><p>youngjae_e</p></button></div>${igPhotos.map(n=>`<article class="ig-post"><div class="ig-post-head">${avatar(3,true)}<b>youngjae_e</b><button style="margin-left:auto" onclick="toast('youngjae_e 的帖子')" aria-label="帖子选项">···</button></div><button style="padding:0;width:100%;display:block" onclick="igPhoto(${n})" aria-label="放大Instagram照片">${img(n,'ig-photo')}</button><div class="ig-actions"><button class="liked" onclick="toggleLike(this)" aria-label="取消点赞" aria-pressed="true">${icon('heart')}</button><button onclick="toast('暂无评论')" aria-label="评论">${icon('chat')}</button><button onclick="toast('已打开分享面板');igShare()" aria-label="分享">${icon('send')}</button><button onclick="this.classList.toggle('liked')" aria-label="收藏">${icon('bookmark')}</button></div><p class="ig-caption"><b>shinyu_u 已点赞</b></p><p class="ig-caption"><b>youngjae_e</b> ${captions[n]}</p><p class="ig-post-time">刚刚</p></article>`).join('')}`}
else if(tab==='profile'){head=`<div class="ig-profile-head"><b>shinyu_u <span>⌄</span></b><div><button onclick="renderIG('create')" aria-label="创建帖子">${icon('plus')}</button><button onclick="igOptions()" aria-label="Instagram菜单">☰</button></div></div>`;content=`<div class="ig-profile"><div class="profile-top"><img src="assets/ig-shinyu-avatar.jpg" class="ig-main-avatar" alt="个人头像"><div class="stats"><b>${ownIGPhotos.length}</b><br>帖子</div><div class="stats"><b>0</b><br>粉丝</div><button class="stats" onclick="youngjaeProfile()"><b>1</b><br>关注</button></div><div class="ig-bio"><p>spring</p></div><div class="ig-profile-buttons"><button onclick="editIGProfile()">编辑个人主页</button><button onclick="youngjaeProfile()" aria-label="发现用户">${icon('user')}</button></div></div><div class="ig-grid-tabs"><button class="selected" onclick="renderIG('profile')" aria-label="帖子网格">${icon('grid')}</button><button onclick="renderIG('reels')" aria-label="主页Reels">${icon('camera')}</button><button onclick="toast('暂无标记帖子')" aria-label="标记帖子">${icon('user')}</button></div><div class="photo-grid ig-own-grid">${ownIGPhotos.map((n,i)=>`<button onclick="ownIGPost(${i})" aria-label="查看帖子${i+1}">${img(n)}</button>`).join('')}</div>`}
else if(tab==='search'){head=`<div class="ig-search-head"><input placeholder="搜索" aria-label="搜索Instagram" oninput="searchIG(this.value)"></div>`;content=`<div class="ig-search-tags"><button onclick="searchIG('')">推荐</button><button onclick="searchIG('youngjae_e')">账号</button><button onclick="searchIG('崔英宰')">标签</button><button onclick="searchIG('')">地点</button></div><div id="ig-search-content"><div class="photo-grid">${igPhotos.map(n=>`<button onclick="igPhoto(${n})">${img(n)}</button>`).join('')}</div></div>`}
else if(tab==='dm'){head=`<div class="ig-profile-head"><button class="back" onclick="renderIG('home')" aria-label="返回Instagram首页">‹</button><b>shinyu_u⌄</b><button onclick="toast('暂无新消息')" aria-label="新消息">${icon('plus')}</button></div>`;content=`<input class="searchbar" placeholder="搜索" aria-label="搜索私信"><div class="stories"><button onclick="toast('暂无便签')"><div class="story-ring own-story"><img src="assets/ig-shinyu-avatar.jpg" alt="个人头像"></div><p>你的便签</p></button></div><div class="ig-message-title">消息</div><div class="empty-state">暂无消息</div>`}
else{head=`<div class="ig-profile-head"><button class="back" onclick="renderIG('home')">‹</button><b>${tab==='activity'?'动态':tab==='create'?'新建帖子':'Reels'}</b><span></span></div>`;content=`<div class="empty-state">${tab==='activity'?'暂无新动态':tab==='create'?'选择相册中的照片':'暂无视频'}</div>${tab==='create'?`<div class="photo-grid">${publicPhotos.map(n=>`<button onclick="toast('本地预览不发布新帖子')">${img(n)}</button>`).join('')}</div>`:''}`}
setView(page(head+`<div class="scroll ig-scroll">${content}</div>`+igBottom(tab),'instagram-page'))}
const ownCaptionChoices={5:['借我握一下。','今天的小小快乐。','柔软的一瞬间。'],6:['绿色刚刚好。','在树荫里。','走进今天的绿色。'],7:['耳机里的这一首。','暂停一小会儿。','等电梯的时候。'],8:['坐下来歇一会儿。','今天是暖色调。','把这一刻留下。'],9:['树影和好天气。','出门走走。','普通的一天也很好。'],10:['今天这一碗。','吃饱再出发。','先认真吃饭。'],11:['慢慢吃，好好过。','今天的餐桌。','喜欢这样的晚饭。'],12:['带一点橘色出门。','今天的小配件。','口袋里的好心情。'],13:['今天也在充电。','什么都不做的一小会儿。','陪你躺一会儿。'],14:['热乎乎的一餐。','好好吃饭。','今天想吃这个。'],15:['被可爱击中了。','今天份的可爱。','看一眼就开心。'],16:['面包香的一天。','带面包回去。','今天的快乐很简单。'],17:['今天的烘焙时间。','认真做一点甜的。','面粉和好心情。'],18:['睡个好觉。','把时间放慢。','安静的一小会儿。'],19:['坐在这里待一会儿。','今天也慢慢来。','记录一个普通的瞬间。'],20:['换个角度。','今天想这样。','近一点。'],21:['顺手记录。','留住今天。','镜头里的这一刻。']};
const ownCaptionCache=new Map();function ownIGCaption(n){if(!ownCaptionCache.has(n)){const choices=ownCaptionChoices[n];ownCaptionCache.set(n,choices[Math.floor(Math.random()*choices.length)])}return ownCaptionCache.get(n)}

function ownIGPost(i){setView(page(`<div class="ig-profile-head"><button class="back" onclick="renderIG('profile')" aria-label="返回个人主页">‹</button><b>帖子</b><span></span></div><div class="scroll"><div class="ig-post-head"><img src="assets/ig-shinyu-avatar.jpg" class="avatar round" alt="个人头像"><b>shinyu_u</b><button style="margin-left:auto" onclick="toast('shinyu_u 的帖子')" aria-label="帖子选项">···</button></div>${img(ownIGPhotos[i],'ig-photo','公开相册照片')}<div class="ig-actions"><button onclick="this.classList.toggle('liked')" aria-label="点赞">${icon('heart')}</button><button onclick="toast('暂无评论')" aria-label="评论">${icon('chat')}</button><button onclick="toast('暂无可分享的对话')" aria-label="分享">${icon('send')}</button><button onclick="this.classList.toggle('liked')" aria-label="收藏">${icon('bookmark')}</button></div><p class="ig-caption"><b>shinyu_u</b> ${escapeHTML(ownIGCaption(ownIGPhotos[i]))}</p></div>`+igBottom('profile'),'instagram-page'))}

function searchIG(query){let el=$('#ig-search-content');if(!el)return;el.innerHTML=query?`<div class="list"><button class="list-row" onclick="youngjaeProfile()">${avatar(3,true)}<span><strong>youngjae_e</strong><p>崔英宰</p></span></button></div>`:`<div class="photo-grid">${igPhotos.map(n=>`<button onclick="igPhoto(${n})">${img(n)}</button>`).join('')}</div>`}
function igOptions(){setView(page(header('设置与动态','','renderIG(\'profile\')')+`<div class="list"><button class="list-row" onclick="editIGProfile()">编辑个人主页</button><button class="list-row" onclick="renderIG('activity')">通知</button><button class="list-row" onclick="toast('暂无已收藏的帖子')">已收藏</button><button class="list-row" onclick="toast('账号：shinyu_u')">账号信息</button></div>`+igBottom('profile'),'instagram-page'))}
function editIGProfile(){setView(page(header('编辑个人主页',`<button class="text-action" onclick="renderIG('profile')">完成</button>`,'renderIG(\'profile\')')+`<div class="ig-edit-profile"><img src="assets/ig-shinyu-avatar.jpg" class="ig-main-avatar" alt="个人头像"><p>编辑照片或虚拟形象</p></div><div class="list"><div class="list-row"><span class="muted">姓名</span></div><div class="list-row"><span class="muted">用户名</span> shinyu_u</div><div class="list-row"><span class="muted">简介</span> spring</div></div>`,'instagram-page'))}
function igShare(){toast('暂无可分享的对话')}

function toggleLike(el){let on=el.classList.toggle('liked');el.setAttribute('aria-pressed',on);el.setAttribute('aria-label',on?'取消点赞':'点赞');let label=el.closest('.ig-post').querySelector('.ig-caption b');if(label)label.textContent=on?'shinyu_u 已点赞':'尚未点赞'}
function youngjaeProfile(){setView(page(header('youngjae_e','','renderIG(\'search\')')+`<div class="scroll"><div class="ig-profile"><div class="profile-top">${avatar(3,true)}<div class="stats">${igPhotos.length}<br>帖子</div></div><p><b>youngjae_e</b></p><p>崔英宰</p></div><div class="photo-grid">${igPhotos.map(n=>`<button onclick="igPhoto(${n})">${img(n)}</button>`).join('')}</div></div>`))}
function igPhoto(n){setView(page(header('youngjae_e','','renderIG()')+`<div class="scroll">${img(n,'attachment-content')}<p class="ig-caption">${captions[n]}</p></div>`))}
let storyTimer=null,storyElapsed=0,storyLastTick=0,storyCommentsOpen=false;const storyComments=[];const STORY_DURATION=5000;
function announceIGStory(){if(state.storyAvailable)return;state.storyAvailable=true;state.phase='story-pending';$('#notification').innerHTML=`<button class="notification" onclick="openEndingIG()"><span class="app-icon instagram">${iosGlyph('instagram')}</span><div><b>Instagram · youngjae_e</b><p>英宰发布了新快拍</p><small>现在 · 轻点打开Instagram</small></div></button>`}
function openEndingIG(){$('#notification').innerHTML='';openApp('instagram');renderIG('home')}
function stopIGStory(){storyCommentsOpen=false;if(storyTimer!==null){clearInterval(storyTimer);storyTimer=null}}
function closeIGStory(){stopIGStory();renderIG('home')}
function finishIGStory(){stopIGStory();if(!state.storyAvailable)return;state.storyViewed=true;updateRound2Completion();renderIG('home')}
function tickIGStory(){const now=Date.now();if(state.app!=='ig-story'){stopIGStory();return}if(!document.hidden&&!storyCommentsOpen)storyElapsed+=now-storyLastTick;storyLastTick=now;const progress=$('#ig-story-progress');if(progress)progress.style.width=Math.min(100,storyElapsed/STORY_DURATION*100)+'%';if(storyElapsed>=STORY_DURATION)finishIGStory()}
function restartIGStory(){storyElapsed=0;storyLastTick=Date.now();const bar=$('#ig-story-progress');if(bar)bar.style.width='0%'}
function showIGStory(){if(!state.storyAvailable){toast('暂无快拍');return}stopIGStory();$('#notification').innerHTML='';state.app='ig-story';storyElapsed=0;storyLastTick=Date.now();setView(page(`<div class="ig-story-progress-track"><span id="ig-story-progress"></span></div><div class="ig-story-head">${avatar(3,true)}<b>youngjae_e</b><span>刚刚</span><button onclick="toast('youngjae_e 的快拍')" aria-label="快拍选项">···</button><button onclick="closeIGStory()" aria-label="关闭快拍">×</button></div><div class="ig-story-picture"><img src="assets/ig-ending-story.jpg" alt="英宰快拍照片"><p class="ig-story-caption">형과 함께</p><button class="ig-story-prev" onclick="restartIGStory()" aria-label="重新查看快拍"></button><button class="ig-story-next" onclick="finishIGStory()" aria-label="看完快拍"></button></div><div class="ig-story-footer"><button class="ig-story-reply" onclick="openStoryComments()" aria-label="查看和发表评论">发表评论…</button><button onclick="this.classList.toggle('liked')" aria-label="喜欢快拍">${icon('heart')}</button><button onclick="toast('暂无可分享的对话')" aria-label="分享快拍">${icon('send')}</button></div>`,'ig-story-page'),true);storyTimer=setInterval(tickIGStory,50)}

function storyCommentRows(){return storyComments.length?storyComments.map(c=>`<article class="story-comment"><img src="assets/ig-shinyu-avatar.jpg" alt="个人头像"><div><b>shinyu_u <small>刚刚</small></b><p>${escapeHTML(c)}</p></div></article>`).join(''):'<p class="story-comments-empty">还没有评论，来说点什么吧</p>'}
function openStoryComments(){if(state.app!=='ig-story'||storyCommentsOpen)return;storyCommentsOpen=true;const panel=document.createElement('div');panel.id='story-comments-panel';panel.className='story-comments-panel';panel.innerHTML=`<button class="story-comments-backdrop" onclick="closeStoryComments()" aria-label="关闭评论"></button><section class="story-comments-sheet" role="dialog" aria-modal="true" aria-label="快拍评论"><div class="story-comments-handle"></div><header><b>评论</b><button onclick="closeStoryComments()" aria-label="关闭评论面板">×</button></header><div class="story-comments-list" id="story-comments-list" aria-live="polite">${storyCommentRows()}</div><form onsubmit="postStoryComment(event)"><img src="assets/ig-shinyu-avatar.jpg" alt="个人头像"><input id="story-comment-input" aria-label="快拍评论内容" placeholder="添加评论…" autocomplete="off" maxlength="1000"><button type="submit">发布</button></form></section>`;$('#view').append(panel)}
function closeStoryComments(){storyCommentsOpen=false;storyLastTick=Date.now();$('#story-comments-panel')?.remove()}
function postStoryComment(event){event.preventDefault();if(!storyCommentsOpen||state.app!=='ig-story')return;const input=$('#story-comment-input');const text=input.value.trim();if(!text)return;storyComments.push(text);input.value='';const list=$('#story-comments-list');list.innerHTML=storyCommentRows();list.scrollTop=list.scrollHeight}


function renderKakao(tab=state.kTab){state.kTab=tab;state.app='kakao';let people=state.call1Done?['영춘','경민','朋友','爸爸','妈妈','姐姐']:['경민','朋友','爸爸','妈妈','姐姐'];let title=tab==='friends'?'好友':tab==='chats'?'聊天':tab==='open'?'开放聊天':tab==='shop'?'购物':'更多';let rows=people.map((name,i)=>{let young=name==='영춘',kyung=name==='경민';return `<button class="list-row" onclick="openChat('${name}')">${avatar(young?3:kyung?2:null)}<span class="grow"><strong>${name}</strong><p>${tab==='friends'?(young?'崔英宰':kyung?'李炅潣':''):young?(state.call2Done?(state.round2Incoming>=3?'ㅎㅎ':state.round2ChatStep>=2?'好想你':state.round2Incoming>=2?'哥在干嘛':state.round2ChatStep?'睡了吗？':''):state.reply|| (state.chatStep>=3?'语音消息':'哥到宿舍了吗？')):kyung?'...':'暂无消息'}</p></span>${young&&state.phase==='chat'?'<span class="badge">1</span>':''}</button>`}).join('');setView(page(header(title,`<button onclick="kakaoSearch()" aria-label="搜索好友">${icon('search')}</button>`)+`<h1 class="large-title">${title}</h1><div class="scroll">${tab==='open'||tab==='shop'?'<div class="empty-state">暂无内容</div>':tab==='more'?`<div class="list"><div class="list-row">${avatar(null)}<span><strong>申正焕</strong><p>我的资料</p></span></div><button class="list-row" onclick="kakaoSettings()">设置 <span class="chevron">›</span></button></div>`:`<div class="list">${tab==='friends'?'<p class="section-label">好友</p>':''}${rows}</div>`}</div>`+tabs([['friends','好友','user'],['chats','聊天','chat'],['open','开放聊天','chat'],['shop','购物','bookmark'],['more','更多','grid']],tab,'renderKakao'),'kakao'))}
function kakaoSearch(){setView(page(header('搜索','','renderKakao()')+`<input class="searchbar" aria-label="搜索好友" placeholder="搜索好友" oninput="document.querySelectorAll('[data-contact]').forEach(e=>e.hidden=!e.dataset.contact.includes(this.value))"><div class="list">${(state.call1Done?['영춘','경민','朋友','爸爸','妈妈','姐姐']:['경민','朋友','爸爸','妈妈','姐姐']).map(n=>`<div data-contact="${n}"><button class="list-row" onclick="openChat('${n}')">${avatar(n==='영춘'?3:n==='경민'?2:null)}${n}</button></div>`).join('')}</div>`))}
function kakaoSettings(){setView(page(header('设置','','renderKakao(\'more\')')+`<div class="list"><div class="list-row">Kakao账号 · 申正焕</div><button class="list-row" onclick="renderKakao('friends')">好友</button><button class="list-row" onclick="renderKakao('chats')">聊天</button><button class="list-row" onclick="toast('已开启故事通知')">通知 · 已开启</button><button class="list-row" onclick="toast('基本主题')">主题 · 基本主题</button></div>`))}
function bubble(dir,text,n=3,group=false,unread=false){if(dir==='date')return `<div class="chat-date">${escapeHTML(text)}</div>`;return `<div class="bubble-row ${dir==='out'?'mine':''} ${group?'grouped-bubble':''}">${dir==='in'?(group?'<span class="avatar-spacer"></span>':avatar(n)):''}<div class="bubble-wrap">${dir==='in'&&!group?`<p class="bubble-name">${n===2?'경민':'영춘'}</p>`:''}<div class="bubble">${escapeHTML(text)}</div>${unread&&!state.reply?'<span class="unread-count">1</span>':''}</div></div>`}

function youngMessages(){let html=bubble('date','17:32')+bubble('in','哥到宿舍了吗？');if(state.chatStep>=1)html+=bubble('out','到了');if(state.chatStep>=2){html+=bubble('out','英宰呢？');if(state.youngArrived)html+=bubble('in','到了喔')}if(state.chatStep>=3){html+=bubble('out','不过英宰是不是刚刚忘记什么了？');if(state.incomingStage>=1)html+=bubble('in','什么？',3,false,true);if(state.incomingStage>=2)html+=bubble('in','哦...',3,true,true);if(state.incomingStage>=3)html+=bubble('in','想起来了',3,true,true);if(state.incomingStage>=4)html+=`<div class="bubble-row grouped-bubble"><span class="avatar-spacer"></span><div class="bubble-wrap"><div class="bubble voice-card"><button class="voice-card-play" onclick="playVoice()" aria-label="播放英宰语音"><span id="voice-icon">▶</span><span>00:03</span></button><div class="voice-transcript"><span>语音识别</span><p>我也喜欢哥</p></div></div>${!state.reply?'<span class="unread-count">1</span>':''}</div></div>`}if(state.reply)html+=bubble('out',state.reply);return html+secondRoundMessages()}

function openChat(name){currentContact=name;state.app='kakao';if(name==='영춘')$('#notification').innerHTML='';let young=name==='영춘',kyung=name==='경민';let script=['到了','英宰呢？','不过英宰是不是刚刚忘记什么了？'];let secondScripted=young&&state.call2Done&&state.round2ChatStep<2&&!state.round2ChatBusy;let scripted=young&&state.phase==='chat'&&state.chatStep<3&&!chatBusy;let free=young&&state.chatStep>=3&&state.voiceReady&&!state.reply&&state.phase==='chat';setView(page(header(name,`<button onclick="toast('${young?'崔英宰':kyung?'李炅潣':name}')" aria-label="联系人信息">☰</button>`,'renderKakao(\'chats\')')+`<div class="scroll chat-messages" id="messages">${young?youngMessages():kyung?kyungmin.map(([d,t],i)=>bubble(d,t,2,i>0&&d==='in'&&kyungmin[i-1][0]==='in')).join(''):'<div class="empty-state">暂无聊天记录</div>'}</div><form class="chat-input" onsubmit="submitChat(event)"><button type="button" class="chat-plus" onclick="toast('暂无附件')" aria-label="添加附件">＋</button><div class="chat-input-shell"><input id="reply-input" aria-label="聊天回复" placeholder="输入消息" value="${secondScripted?['睡了吗？','好想你'][state.round2ChatStep]:scripted?script[state.chatStep]:''}" ${scripted||secondScripted?'readonly':free?'':'disabled'} autocomplete="off"><button type="button" class="chat-smile" onclick="toast('☺')" aria-label="表情">☺</button></div>${scripted||free||secondScripted?'<button class="chat-send" type="submit" aria-label="发送消息">发送</button>':'<button type="button" class="chat-mic" onclick="toast(\'未开启录音\')" aria-label="录音"><svg class="chat-mic-icon" viewBox="0 0 24 24" aria-hidden="true"><rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5.5 10.5v1.5a6.5 6.5 0 0 0 13 0v-1.5M12 18.5V22M8.5 22h7"/></svg></button>'}</form>`,'chat-page'));if(young)setTimeout(()=>{if($('#messages'))$('#messages').scrollTop=$('#messages').scrollHeight},0)}
function submitChat(e){e.preventDefault();if(currentContact==='영춘'&&state.call2Done){sendSecondRoundChat();return}if(state.phase==='chat'&&state.chatStep<3)sendScript();else sendReply(e)}

function refreshYoungChat(){if(state.app==='kakao'&&currentContact==='영춘')openChat('영춘')}
function sendScript(){if(chatBusy||state.phase!=='chat'||state.chatStep>=3)return;state.chatStep++;if(state.chatStep===2){chatBusy=true;refreshYoungChat();setTimeout(()=>{if(state.phase!=='chat')return;state.youngArrived=true;chatBusy=false;refreshYoungChat()},700);return}if(state.chatStep===3){chatBusy=true;state.voiceReady=false;state.incomingStage=0;refreshYoungChat();[700,1450,2250,3100].forEach((delay,i)=>setTimeout(()=>{if(state.phase!=='chat')return;state.incomingStage=i+1;if(i===3){state.voiceReady=true;chatBusy=false}refreshYoungChat();if(i===3)playVoice()},delay));return}refreshYoungChat()}
async function playVoice(){if(!state.voiceReady||state.callNumber)return;voiceResumeMusic=voiceResumeMusic||!music.paused;music.pause();voice.currentTime=0;if(await playSafe(voice)){state.voiceHeard=true;if($('#voice-icon'))$('#voice-icon').textContent='❚❚'}voice.onended=()=>{if($('#voice-icon'))$('#voice-icon').textContent='▶';if(voiceResumeMusic&&!state.callNumber){voiceResumeMusic=false;playSafe(music)}}}

function sendReply(e){e.preventDefault();if(state.phase!=='chat'||state.chatStep<3||state.reply)return;let text=$('#reply-input').value.trim();if(!text)return;if(!state.voiceHeard){toast('请先收听英宰的语音');return}if(!voice.paused){toast('听完这条语音，再回复吧。');return}state.reply=text;state.phase='call2-ringing';openChat('영춘');setTimeout(()=>incomingCall(2),750)}
function showNotification(){let el=$('#notification');el.innerHTML=`<button class="notification" onclick="openChat('영춘')"><span class="app-icon kakao"><span class="kakao-logo">TALK</span></span><div><b>KakaoTalk · 영춘</b><p>哥到宿舍了吗？</p><small>现在 · 轻点回复</small></div></button>`}
function xAvatar(author='self'){return author==='young'?`<svg class="avatar round x-young-avatar" viewBox="28 24 158 158" role="img" aria-label="英宰X头像"><image href="assets/round2-x-01.jpg" width="1179" height="1281"/></svg>`:`<img class="avatar round" src="assets/x-avatar.png" alt="申正焕X头像">`}
function xLock(){return '<svg class="x-lock" viewBox="0 0 16 18" aria-label="私密账号"><path d="M4 7V4a4 4 0 0 1 8 0v3" fill="none" stroke="currentColor" stroke-width="1.8"/><rect x="1" y="7" width="14" height="11" rx="2" fill="currentColor"/></svg>'}
function xMetrics(index,detail=false,author='self'){const list=author==='young'?youngXTweets:tweets;return `<div class="tweet-metrics ${detail?'detail-metrics':''}"><button aria-label="查看回复" onclick="event.stopPropagation();tweetDetail(${index},'${author}')">${icon('chat')}<span>${list[index].replies.length+(author==='young'?youngXCommentCount(index):0)||''}</span></button><button aria-label="转发" onclick="event.stopPropagation();toast('这是私密帖子')"><svg class="icon-svg" viewBox="0 0 24 24"><path d="m3 7 4-4 4 4M7 3v14h9M21 17l-4 4-4-4M17 21V7H8"/></svg></button><button aria-label="喜欢帖子" onclick="event.stopPropagation();this.classList.toggle('liked')">${icon('heart')}</button><button aria-label="帖子浏览" onclick="event.stopPropagation();toast('私密帖子')"><svg class="icon-svg" viewBox="0 0 24 24"><path d="M4 20V11M10 20V3M16 20V8M22 20V14"/></svg></button><button aria-label="分享帖子" onclick="event.stopPropagation();toast('这是私密帖子')">${icon('send')}</button></div>`}
function xTweet(t,i,reply=false,author='self'){const info=xAuthor(author);return `<article class="tweet ${reply?'x-thread-reply':''}"><button class="x-avatar-button" onclick="${author==='young'?'youngXProfile()':"renderX('profile')"}" aria-label="查看${author==='young'?'英宰':'我的'}X主页">${xAvatar(author)}</button><div class="tweet-content"><button class="tweet-open" onclick="tweetDetail(${i},'${author}')"><div class="tweet-name">${info.name} ${xLock()} <span>@${info.handle} · ${tweetDate(t)}</span><i>···</i></div><p class="tweet-body">${escapeHTML(t.body)}</p></button>${xMetrics(i,false,author)}</div></article>`}
function xBottom(tab){return `<nav class="tabbar x-tabbar">${[['home','首页','home'],['search','搜索','search'],['grok','Grok','grid'],['notifications','通知','bell'],['dm','私信','mail']].map(([id,label,ic])=>`<button class="${id===tab?'active':''}" aria-label="X${label}" onclick="renderX('${id}')">${icon(ic)}</button>`).join('')}</nav>`}
function renderX(tab=state.xTab){state.xDetailAuthor='';state.xDetailIndex=-1;state.app='x';state.xTab=tab;let content='',head='';
if(tab==='home'){head=`<div class="x-top"><button onclick="xDrawer()" aria-label="打开X账号菜单">${xAvatar()}</button><span class="x-logo">𝕏</span><button onclick="toast(state.youngXUnlocked?'显示已解锁的关注账号':'仅显示自己的帖子')" aria-label="时间线设置">✧</button></div>`;content=`<div class="x-tabs"><button onclick="renderX('home')">为你推荐</button><button class="active" onclick="renderX('home')">正在关注</button></div>${newXFollowNotice()}${xTimelineHTML()}`}
else if(tab==='profile'){head=`<div class="x-profile-top"><button onclick="renderX('home')" aria-label="返回X首页">‹</button><button onclick="renderX('search')" aria-label="搜索自己的帖子">${icon('search')}</button><button onclick="xDrawer()" aria-label="更多账号选项">···</button></div>`;content=`<div class="x-profile-cover"></div><div class="x-profile-info"><img class="x-profile-avatar" src="assets/x-avatar.png" alt="申正焕X头像"><button class="x-edit-button" onclick="xProfileEditor()">编辑个人资料</button><p class="x-name">신정환 ${xLock()}</p><p class="x-handle">@loveguineapig</p><p class="x-bio">春天什么时候来</p><p class="x-stats" onclick="xConnections()" role="button" tabindex="0" onkeydown="if(event.key==='Enter')xConnections()"><b>1</b> 正在关注　 <b>${state.youngXUnlocked?12:11}</b> 关注者</p></div><div class="x-tabs profile-tabs"><button class="active" onclick="renderX('profile')">帖子</button><button onclick="xQuiet('回复')">回复</button><button onclick="xQuiet('亮点')">亮点</button><button onclick="xQuiet('媒体')">媒体</button><button onclick="xQuiet('喜欢')">喜欢</button></div>${[...tweets].reverse().map((t,j)=>xTweet(t,5-j)).join('')}`}
else if(tab==='search'){head=`<div class="x-search-head"><button onclick="xDrawer()" aria-label="打开X账号菜单">${xAvatar()}</button><input placeholder="搜索X上的内容" aria-label="搜索X帖子" oninput="filterTweets(this.value)"><button onclick="toast('仅搜索本账号内容')" aria-label="搜索设置">${icon('settings')}</button></div>`;content=`<div class="x-tabs"><button class="active" onclick="renderX('search')">为你推荐</button><button onclick="toast('无其他用户内容')">趋势</button><button onclick="toast('无其他用户内容')">新闻</button><button onclick="toast('无其他用户内容')">体育</button></div><div id="search-tweets">${state.youngXUnlocked?youngXAccountRow():''}${xTimelineHTML(true)}</div>`}
else if(tab==='dm'){head=`<div class="x-simple-head"><b>私信</b><button onclick="toast('暂无新的私信')" aria-label="新私信">${icon('plus')}</button></div>`;content='<input class="searchbar" placeholder="搜索私信" aria-label="搜索私信"><div class="empty-state">暂无私信</div>'}
else if(tab==='notifications'){head=`<div class="x-simple-head"><button onclick="xDrawer()" aria-label="打开X账号菜单">${xAvatar()}</button><b>通知</b><button onclick="toast('通知已开启')" aria-label="通知设置">${icon('settings')}</button></div>`;content=`${state.youngXUnlocked?newXFollowNotice(true):''}<div class="x-tabs"><button class="active">全部</button><button onclick="toast(\'暂无认证通知\')">认证</button><button onclick="toast(\'暂无提及\')">提及</button></div>${!state.youngXUnlocked?'<div class="empty-state">暂无通知</div>':''}`}
else{head=header('Grok','','renderX(\'home\')');content='<div class="empty-state">暂无对话</div>'}
setView(page(head+`<div class="scroll">${content}</div>`+xBottom(tab),'x-page'))}
function xDrawer(){let panel=document.createElement('div');panel.className='x-drawer-shade';panel.innerHTML=`<button class="x-drawer-dismiss" onclick="this.parentElement.remove()" aria-label="关闭账号菜单"></button><aside class="x-drawer"><button onclick="this.closest('.x-drawer-shade').remove();renderX('profile')">${xAvatar()}</button><p class="x-name">신정환 ${xLock()}</p><p class="x-handle">@loveguineapig</p><p class="x-stats" onclick="xConnections()" role="button" tabindex="0" onkeydown="if(event.key==='Enter')xConnections()"><b>1</b> 正在关注　<b>${state.youngXUnlocked?12:11}</b> 关注者</p><div class="x-drawer-links"><button onclick="this.closest('.x-drawer-shade').remove();renderX('profile')">${icon('user')}个人主页</button><button onclick="toast('暂无Premium内容')"><span>𝕏</span>Premium</button><button onclick="toast('暂无书签')">${icon('bookmark')}书签</button><button onclick="toast('暂无列表')">${icon('list')}列表</button><button onclick="toast('暂无话题')"><span>＃</span>话题</button></div><div class="x-drawer-links minor"><button onclick="toast('当前账号为私密账号')">${icon('settings')}设置与隐私</button><button onclick="toast('lovewinsall')">帮助中心</button><button onclick="state.dark=!state.dark;this.closest('.x-drawer-shade').remove();renderX()">夜间模式</button></div></aside>`;$('#screen').append(panel)}
function xProfileEditor(){setView(page(header('编辑个人资料',`<button class="text-action" onclick="renderX('profile')">保存</button>`,'renderX(\'profile\')')+`<div class="x-profile-cover"></div><div class="list"><div class="list-row">名称　신정환</div><div class="list-row">简介　春天什么时候来</div><div class="list-row">账号　@loveguineapig</div></div>`,'x-page'))}

function filterTweets(q){document.querySelectorAll('[data-tweet]').forEach(e=>e.hidden=!e.dataset.tweet.includes(q))}
function xQuiet(name){setView(page(`<div class="x-simple-head"><button class="back" onclick="renderX('profile')" aria-label="返回个人主页">‹</button><b>${name}</b><span></span></div><div class="scroll">${name==='回复'?tweets.map((t,i)=>t.replies.map(r=>`<article class="tweet"><div>${xAvatar()}</div><div class="tweet-content"><button class="tweet-open" onclick="tweetDetail(${i})"><div class="tweet-name">신정환 ${xLock()} <span>@loveguineapig</span></div><p class="x-reply-to">回复 @loveguineapig</p><p class="tweet-body">${escapeHTML(r)}</p></button>${xMetrics(i)}</div></article>`).join('')).join(''):'<div class="empty-state">暂无内容</div>'}</div>`+xBottom('profile'),'x-page'))}

function tweetDetail(i,author='self'){if(author==='young'&&!state.youngXUnlocked)return;state.app='x';state.xDetailAuthor=author;state.xDetailIndex=i;const t=(author==='young'?youngXTweets:tweets)[i],info=xAuthor(author);const back=author==='young'?'youngXProfile()':'renderX()';setView(page(`<div class="x-simple-head"><button class="back" onclick="${back}" aria-label="返回X时间线">‹</button><b>帖子</b><span></span></div><div class="scroll"><div class="tweet-detail"><div class="x-detail-author"><button class="x-avatar-button" onclick="${author==='young'?'youngXProfile()':"renderX('profile')"}">${xAvatar(author)}</button><div><b>${info.name} ${xLock()}</b><p class="x-handle">@${info.handle}</p></div><button onclick="toast('这是私密帖子')" aria-label="帖子选项">···</button></div><p class="tweet-body">${escapeHTML(t.body)}</p><p class="x-full-date">${tweetDate(t,true)}</p>${xMetrics(i,true,author)}</div>${t.replies.map((r,j)=>`<article class="tweet x-thread-reply"><div class="x-thread-avatar">${xAvatar(author)}${j<t.replies.length-1?'<span></span>':''}</div><div class="tweet-content"><div class="tweet-name">${info.name} ${xLock()} <span>@${info.handle}</span><i>···</i></div><p class="x-reply-to">回复 <span>@${info.handle}</span></p><p class="tweet-body">${escapeHTML(r)}</p>${xMetrics(i,false,author)}</div></article>`).join('')}${author==='young'?youngXCommentThreads(i):''}</div>${author==='young'?youngXComposer(i):`<div class="x-reply-composer"><button onclick="toast('暂无新的回复')">发布你的回复</button></div>`}`,'x-page'))}

function xReference(){setView(page(header('X主页原稿','','renderX(\'profile\')')+`<div class="scroll">${img(56,'tweet-original','用户提供的X主页原稿')}</div>`))}
function tweetReference(i){setView(page(header('帖子原稿','',`tweetDetail(${i})`)+`<div class="scroll">${img(57+i,'tweet-original','用户提供的帖子原稿')}</div>`))}
function incomingCall(number){if(state.callNumber||(number===1&&state.call1Done)||(number===2&&state.call2Done))return;closePhoto();state.returnMusic=!music.paused||voiceResumeMusic;voiceResumeMusic=false;music.pause();voice.pause();state.callNumber=number;state.callActive=false;state.callMuted=false;state.callSpeaker=false;$('#notification').innerHTML='';renderCall()}
state.translateEnabled=true;
function callGlyph(name){const paths={mute:'M9 3v9a3 3 0 0 0 5 2M15 9V3a3 3 0 0 0-6 0M5 9v3a7 7 0 0 0 12 5M19 9v3M12 19v4M8 23h8M2 2l20 20',video:'M2 5h14v14H2zM16 9l6-4v14l-6-4',person:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M16 9a4 4 0 1 1-8 0 4 4 0 0 1 8 0M5 19a7 7 0 0 1 14 0',plus:'M12 3v18M3 12h18'};if(name==='keypad')return `<svg class="icon-svg" viewBox="0 0 24 24">${[5,12,19].map(y=>[5,12,19].map(x=>`<circle cx="${x}" cy="${y}" r="2" fill="currentColor" stroke="none"/>`).join('')).join('')}</svg>`;if(name==='speaker')return icon('volume');return `<svg class="icon-svg" viewBox="0 0 24 24"><path d="${paths[name]}"/></svg>`}
function callTime(seconds){return String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(Math.floor(seconds%60)).padStart(2,'0')}
function updateCallSubtitle(){const el=$('#call-subtitle');if(!el)return;let cues=window.CALL_TRANSLATIONS?.[state.callNumber]||[];let at=callAudio.currentTime;let cue=cues.find(c=>at>=c.start&&at<c.end);el.textContent=state.translateEnabled?(cue?.text||''):''}
function toggleTranslation(){state.translateEnabled=!state.translateEnabled;renderCall();updateCallSubtitle()}
function renderCall(){let name=state.callNumber===1?'未知用户':'英宰';$('#call-layer').innerHTML=`<div class="call-layer"><h2>${name}</h2><div class="call-sub">${state.callActive?`<span id="call-time">${callTime(callAudio.currentTime)}</span>`:'手机<br>韩国'}</div>${state.callActive?`<div class="live-translation"><button onclick="toggleTranslation()" aria-pressed="${state.translateEnabled}" aria-label="切换实时翻译">${state.translateEnabled?'▣ 实时翻译':'▣ 开启翻译'}</button><p id="call-subtitle" aria-live="polite"></p></div><div class="call-controls"><button onclick="toggleCallMute()" aria-pressed="${state.callMuted}" aria-label="静音"><span>${callGlyph('mute')}</span>静音</button><button onclick="callKeypad()"><span>${callGlyph('keypad')}</span>拨号键盘</button><button onclick="toggleSpeaker()" aria-pressed="${state.callSpeaker}"><span>${callGlyph('speaker')}</span>免提</button><button onclick="toast('剧情通话中无法添加通话')"><span>${callGlyph('plus')}</span>添加通话</button><button onclick="toast('暂无视频通话')"><span>${callGlyph('video')}</span>FaceTime</button><button onclick="toast('${name}')"><span>${callGlyph('person')}</span>通讯录</button></div><button class="hangup" disabled aria-label="通话结束后自动挂断">${icon('phone')}</button><p class="call-tip">通话结束后自动挂断</p>`:`<button class="answer" onclick="answerCall()" aria-label="接听${name}来电">${icon('phone')}</button><div class="answer-caption">接听</div>`}<button id="call-retry" class="text-action" style="display:none;color:#fff" onclick="playSafe(callAudio)">点击继续播放通话</button></div>`;$('#screen').classList.add('light-text','in-call');updateCallSubtitle()}
async function answerCall(){if(!state.callNumber||state.callActive)return;state.callActive=true;callAudio.src=A['音频'+(state.callNumber===1?1:4)];callAudio.currentTime=0;callAudio.muted=false;renderCall();if(!await playSafe(callAudio))$('#call-retry').style.display='block'}

function toggleCallMute(){state.callMuted=!state.callMuted;renderCall();toast(state.callMuted?'模拟麦克风已静音，通话音频继续播放':'模拟麦克风已开启')}
function toggleSpeaker(){state.callSpeaker=!state.callSpeaker;renderCall();toast('音频通过当前设备播放；实际扬声器由浏览器控制')}
function callKeypad(){toast('剧情通话中无需拨号')}
callAudio.addEventListener('timeupdate',()=>{if($('#call-time'))$('#call-time').textContent=callTime(callAudio.currentTime);updateCallSubtitle()});
callAudio.addEventListener('ended',()=>{let n=state.callNumber;if(!n)return;state.callNumber=0;state.callActive=false;$('#screen').classList.remove('in-call');$('#call-layer').innerHTML='';if(n===1){state.call1Done=true;state.phase='chat';renderHome();showNotification()}else{state.call2Done=true;unlockSecondRound();openChat('영춘');announceIGStory()}if(state.returnMusic)playSafe(music)});
callAudio.addEventListener('error',()=>{if(state.callNumber){toast('通话音频加载失败，请检查本地服务');if($('#call-retry'))$('#call-retry').style.display='block'}});
function renderPhone(tab='recent'){let recents=['영춘','未知用户',...shuffle(['경민','朋友1','爸爸','妈妈','大姐','二姐'])];let content=tab==='keypad'?`<div class="panel"><input class="searchbar" style="width:100%;margin:20px 0" id="dial-number" aria-label="模拟拨号号码" readonly><div class="keypad" style="color:#333;justify-content:center">${[1,2,3,4,5,6,7,8,9,'*',0,'#'].map(n=>`<button style="background:#eee" onclick="$('#dial-number').value+='${n}'">${n}</button>`).join('')}</div><button class="primary" style="display:block;margin:20px auto" onclick="toast('模拟手机不拨打真实电话')">呼叫</button></div>`:tab==='voicemail'?'<div class="empty-state">暂无语音留言</div>':`<div class="list">${(tab==='contacts'?['영춘','경민','朋友1','爸爸','妈妈','大姐','二姐']:tab==='favorites'?['영춘']:recents).map((n,i)=>`<button class="list-row" onclick="contactDetail('${n}')">${avatar(n==='영춘'?3:n==='경민'?2:null)}<span class="grow"><strong>${n==='영춘'?'崔英宰':n==='경민'?'李炅潣':n}</strong><p>${tab==='contacts'?'手机':'↙ 电话'}</p></span><span class="muted">${i<2?'今天':'昨天'}</span><span class="text-action">ⓘ</span></button>`).join('')}</div>`;setView(page(header('电话')+`<h1 class="large-title">${{recent:'最近通话',contacts:'联系人',favorites:'个人收藏',keypad:'拨号键盘',voicemail:'语音留言'}[tab]}</h1><div class="scroll">${content}</div>`+tabs([['favorites','个人收藏','heart'],['recent','最近通话','clock'],['contacts','联系人','user'],['keypad','拨号键盘','grid'],['voicemail','语音留言','mail']],tab,'renderPhone')))}
function contactDetail(n){setView(page(header('联系人','','renderPhone()')+`<div class="panel" style="text-align:center">${avatar(n==='영춘'?3:n==='경민'?2:null)}<h2>${n}</h2><button class="primary" onclick="toast('请通过故事来电继续；此处不拨打真实电话')">通话</button>${n==='영춘'&&state.call1Done?'<button class="primary" style="margin-left:10px" onclick="openChat(\'영춘\')">KakaoTalk</button>':''}</div>`))}
function renderCalendar(){let y=state.calendarYear,m=state.calendarMonth,first=new Date(y,m,1).getDay(),count=new Date(y,m+1,0).getDate(),today=new Date();let chosen=`${y}-${m+1}-${state.calendarDay}`;let events={'2025-11-7':'遇见','2026-5-31':'英宰生日'};setView(page(header('日历',`<button class="text-action" onclick="calendarToday()">今天</button>`)+`<div class="scroll"><div class="calendar-head"><button class="text-action" onclick="changeMonth(-1)" aria-label="上个月">‹</button><h2>${y}年${m+1}月</h2><button class="text-action" onclick="changeMonth(1)" aria-label="下个月">›</button></div><div class="calendar-grid">${['日','一','二','三','四','五','六'].map(w=>`<span class="weekday">${w}</span>`).join('')}${'<span></span>'.repeat(first)}${Array.from({length:count},(_,i)=>`<button class="calendar-day ${i+1===state.calendarDay?'selected':''} ${y===today.getFullYear()&&m===today.getMonth()&&i+1===today.getDate()?'today':''} ${events[`${y}-${m+1}-${i+1}`]?'event':''}" onclick="state.calendarDay=${i+1};renderCalendar()">${i+1}</button>`).join('')}</div><h3 style="margin:22px 18px">${m+1}月${state.calendarDay}日</h3>${events[chosen]?`<div class="event-card">${events[chosen]}<p class="muted">全天</p></div>`:'<p class="muted" style="margin:18px">没有安排</p>'}<div class="list"><p class="section-label">重要日期</p><button class="list-row" onclick="jumpDate(2025,10,7)"><span class="grow">遇见</span><span class="muted">2025.11.07</span>›</button><button class="list-row" onclick="jumpDate(2026,4,31)"><span class="grow">英宰生日</span><span class="muted">2026.05.31</span>›</button></div></div>`))}
function jumpDate(y,m,d){state.calendarYear=y;state.calendarMonth=m;state.calendarDay=d;renderCalendar()}
function changeMonth(dir){let d=new Date(state.calendarYear,state.calendarMonth+dir,1);jumpDate(d.getFullYear(),d.getMonth(),1)}
function calendarToday(){let d=new Date();jumpDate(d.getFullYear(),d.getMonth(),d.getDate())}
Object.assign(icons,{share:'M12 16V2M8 6l4-4 4 4M8 10H4v12h16V10h-4',compose:'M14 3H3v18h18V10M10 14l1-5L20 1l3 3-9 9z',cloud:'M6 19a5 5 0 0 1-1-10 7 7 0 0 1 13-2 6 6 0 0 1 0 12z',folder:'M2 6V3h7l3 3h10v15H2zM2 9h20',trash:'M4 6h16M9 6V3h6v3M6 6l1 16h10l1-16M10 10v8M14 10v8'});
let noteEditingIndex=-1;
function notesDate(n){return new Date(n.createdAt||Date.now()).toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric'})+' '+new Date(n.createdAt||Date.now()).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}
function notesToolbar(index=-1){return `<div class="notes-toolbar">${index<0?`<span class="notes-total">${notes.length}则备忘录</span>`:`<button onclick="toggleNoteChecklist(${index})" aria-label="清单">${icon('reminders')}</button><button onclick="notePhotoPicker(${index})" aria-label="添加照片">${icon('camera')}</button><button onclick="noteFormatMenu(${index})" aria-label="文本格式"><span class="notes-aa">Ⓐ</span></button>`}<button onclick="newNote()" aria-label="新建备忘录"><svg class="icon-svg" viewBox="0 0 24 24"><path d="M14 3H3v18h18V10M10 14l1-5L20 1l3 3-9 9z"/></svg></button></div>`}
function notesRows(){return notes.map((n,i)=>`<button class="native-note-row" onclick="renderNotes(${i})"><b>${escapeHTML(n.title)}</b><p><time>${new Date(n.createdAt||Date.now()).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}</time> ${escapeHTML(n.sub)}</p></button>`).join('')}
function renderNotes(index=-1){state.app='notes';state.notesIndex=index;notes.forEach(n=>{if(!n.createdAt)n.createdAt=Date.now()-(n.title==='又见面了'?7*24*60*60*1000:0)});if(index<0){setView(page(`<div class="notes-top"><button onclick="toast('选择一则备忘录查看')">编辑</button><button onclick="newNote()" aria-label="新建备忘录">${icon('compose')}</button></div><div class="scroll"><h1 class="large-title">备忘录</h1><div class="notes-search">${icon('search')}<input aria-label="搜索备忘录" placeholder="搜索" oninput="filterNotes(this.value)"></div><div class="notes-folders"><button onclick="notesFolder('iCloud')">${icon('cloud')}<strong>iCloud</strong><i>${notes.length} ›</i></button><button onclick="notesFolder('备忘录')">${icon('folder')}<strong>备忘录</strong><i>${notes.length} ›</i></button><button onclick="notesFolder('已删除')">${icon('trash')}<strong>已删除</strong><i>0 ›</i></button></div><h3 class="notes-section">今天</h3><div class="native-notes-list" id="notes-results">${notesRows()}</div></div>`+notesToolbar(),'notes-page notes-home'));return}let n=notes[index];let lines=n.body.split('\n');let checklist=lines.filter(l=>l.trim()).every(l=>l.startsWith('□ '));let body=checklist?`<div class="native-note-checklist">${lines.filter(l=>l.trim()).map((line,i)=>`<button class="native-note-check ${n.checks?.[i]?'is-done':''}" onclick="toggleNoteCheck(${index},${i})" aria-label="${n.checks?.[i]?'取消勾选':'勾选'}${escapeHTML(line.slice(2))}"><span>${n.checks?.[i]?'✓':''}</span><b>${escapeHTML(line.slice(2))}</b></button>`).join('')}</div>`:`<div class="note-body ${n.largeText?'note-large-text':''}">${escapeHTML(n.body)}</div>`;setView(page(`<div class="notes-detail-top"><button onclick="renderNotes()">‹ 备忘录</button><div><button onclick="toast('此备忘录未分享')" aria-label="分享备忘录">${icon('share')}</button><button onclick="noteOptions(${index})" aria-label="备忘录选项">···</button></div></div><div class="scroll"><h2 class="native-note-title">${escapeHTML(n.title)}</h2><p class="native-note-date">${notesDate(n)}</p>${body}${(n.attachments||[]).map(photo=>img(photo,'note-attachment','备忘录照片')).join('')}</div>`+notesToolbar(index),'notes-page notes-detail'))}
function notesFolder(name){setView(page(`<div class="notes-detail-top"><button onclick="renderNotes()">‹ 文件夹</button><div><button onclick="newNote()">编辑</button></div></div><h1 class="large-title">${name}</h1><div class="scroll"><div class="native-notes-list">${name==='已删除'?'<div class="empty-state">没有备忘录</div>':notesRows()}</div></div>`+notesToolbar(),'notes-page notes-home'))}
function filterNotes(q){document.querySelectorAll('.native-note-row').forEach(row=>row.hidden=!row.textContent.includes(q));$('.notes-folders').hidden=!!q}
function toggleNoteCheck(index,item){let n=notes[index];if(!n.checks)n.checks=[];n.checks[item]=!n.checks[item];renderNotes(index)}
function toggleNoteChecklist(index){let n=notes[index],lines=n.body.split('\n');let check=lines.filter(l=>l.trim()).every(l=>l.startsWith('□ '));n.body=lines.map(l=>check?l.replace(/^□ /,''):l.trim()?'□ '+l:l).join('\n');n.checks=[];renderNotes(index)}
function noteOptions(index){setView(page(`<div class="notes-detail-top"><button onclick="renderNotes(${index})">‹ 备忘录</button></div><div class="list"><button class="list-row" onclick="editNote(${index})">编辑备忘录</button><button class="list-row" onclick="noteFormatMenu(${index})">文本格式</button><button class="list-row" onclick="notePhotoPicker(${index})">添加照片</button></div>`,'notes-page'))}
function noteFormatMenu(index){setView(page(`<div class="notes-detail-top"><button onclick="renderNotes(${index})">‹ 备忘录</button><b>格式</b></div><div class="list"><button class="list-row" onclick="notes[${index}].largeText=true;renderNotes(${index})">标题</button><button class="list-row" onclick="notes[${index}].largeText=false;renderNotes(${index})">正文</button><button class="list-row" onclick="toggleNoteChecklist(${index})">核对清单</button></div>`,'notes-page'))}
function notePhotoPicker(index){setView(page(`<div class="notes-detail-top"><button onclick="renderNotes(${index})">取消</button><b>照片图库</b></div><div class="scroll photo-grid">${publicPhotos.map(n=>`<button onclick="if(!notes[${index}].attachments)notes[${index}].attachments=[];notes[${index}].attachments.push(${n});renderNotes(${index})" aria-label="插入照片${n}">${img(n)}</button>`).join('')}</div>`,'notes-page'))}
function noteEditor(index=-1){noteEditingIndex=index;let n=index>=0?notes[index]:{title:'',body:''};setView(page(`<div class="notes-detail-top"><button onclick="renderNotes(${index>=0?index:-1})">取消</button><button onclick="saveNote()">完成</button></div><input class="notes-title-input" id="note-title" aria-label="备忘录标题" placeholder="标题" value="${escapeHTML(n.title)}"><textarea class="notes-body-input" id="note-content" aria-label="备忘录内容" placeholder="写点什么">${escapeHTML(n.body)}</textarea>`,'notes-page'))}
function newNote(){noteEditor(-1)}
function editNote(index){noteEditor(index)}
function saveNote(){let title=$('#note-title').value.trim(),body=$('#note-content').value.trim();if(!title&&!body)return renderNotes();let n={title:title||'新备忘录',sub:body.replace(/□ /g,'').slice(0,25),body,createdAt:Date.now()};if(noteEditingIndex>=0){Object.assign(notes[noteEditingIndex],n);renderNotes(noteEditingIndex)}else{notes.unshift(n);renderNotes(0)}}

function reminderCounts(){return {today:reminders.filter(r=>!r.done).length,scheduled:reminders.filter(r=>!r.done).length,all:reminders.length,flagged:reminders.filter(r=>r.text==='和英宰见面'&&!r.done).length,completed:reminders.filter(r=>r.done).length,assigned:0}}
function renderReminders(){const counts=reminderCounts();const cards=[['today','今天','calendar','#007aff'],['scheduled','计划','calendar','#ff3b30'],['all','全部','tray','#5c626a'],['flagged','已标记','flag','#ff9f0a'],['completed','已完成','check','#34c759'],['assigned','分配','user','#af52de']];const lists=[['study','学习',reminders.filter(r=>r.type==='公共课程'&&!r.done).length,'#007aff','book'],['work','工作',0,'#ff453a','briefcase'],['life','生活',reminders.filter(r=>r.type!=='公共课程'&&!r.done).length,'#34c759','home'],['travel','旅行',0,'#af52de','plane'],['shopping','购物',0,'#ff9f0a','cart']];setView(page(`<div class="reminder-top"><span></span><div><button onclick="toast('点击列表可编辑提醒事项')">编辑</button><button onclick="newReminder()" aria-label="新建提醒事项">＋</button></div></div><div class="scroll"><h1 class="large-title">提醒事项</h1><div class="reminder-search"><span>${icon('search')}</span><input placeholder="搜索" aria-label="搜索提醒事项" oninput="searchReminders(this.value)"></div><div id="reminder-dashboard"><div class="reminder-cards">${cards.map(([id,label,ic,color])=>`<button onclick="reminderList('${id}')"><div><span class="reminder-card-icon" style="background:${color}">${icon(ic)}</span><b>${counts[id]}</b></div><strong>${label}</strong></button>`).join('')}</div><h2 class="reminder-lists-title">我的列表 <span>⌄</span></h2><div class="reminder-my-lists">${lists.map(([id,label,count,color,ic])=>`<button onclick="reminderList('${id}')"><span class="reminder-card-icon" style="background:${color}">${icon(ic)}</span><strong>${label}</strong><span class="reminder-count">${count}</span><i>›</i></button>`).join('')}</div></div><div id="reminder-search-results" class="list"></div></div>`,'reminders-home grouped'))}
function reminderItems(id){return reminders.map((r,i)=>({...r,index:i})).filter(r=>id==='completed'?r.done:id==='all'?true:id==='flagged'?r.text==='和英宰见面'&&!r.done:id==='study'?r.type==='公共课程'&&!r.done:id==='life'?r.type!=='公共课程'&&!r.done:['work','travel','shopping','assigned'].includes(id)?false:!r.done)}
function reminderList(id){let name={today:'今天',scheduled:'计划',all:'全部',flagged:'已标记',completed:'已完成',assigned:'分配',study:'学习',work:'工作',life:'生活',travel:'旅行',shopping:'购物'}[id];let color={today:'#007aff',scheduled:'#ff3b30',all:'#5c626a',flagged:'#ff9f0a',completed:'#34c759',assigned:'#af52de',study:'#007aff',life:'#34c759',travel:'#af52de',shopping:'#ff9f0a'}[id]||'#ff453a';setView(page(`<div class="reminder-list-head"><button onclick="renderReminders()">‹ 提醒事项</button><div><button onclick="toast('此列表未分享')" aria-label="分享列表">${icon('send')}</button><button onclick="toast('点击圆圈标记完成')" aria-label="列表选项">···</button></div></div><div class="scroll"><h1 class="large-title" style="color:${color}">${name}</h1><div class="list">${reminderItems(id).map(r=>`<div class="reminder-row ${r.done?'done':''}"><button class="check ${r.done?'checked':''}" style="${r.done?'background:'+color+';border-color:'+color:''}" onclick="reminders[${r.index}].done=!reminders[${r.index}].done;reminderList('${id}')" aria-label="${r.done?'取消完成':'完成'}${escapeHTML(r.text)}">${r.done?'✓':''}</button><div><span>${escapeHTML(r.text)}</span><p class="muted">${r.type}</p></div></div>`).join('')}</div></div><button class="new-reminder-footer" style="color:${color}" onclick="newReminder()"><span>＋</span>新提醒事项</button>`,'reminders-list-page'))}
function searchReminders(q){let dash=$('#reminder-dashboard'),results=$('#reminder-search-results');dash.hidden=!!q;results.innerHTML=q?reminders.map((r,i)=>({r,i})).filter(({r})=>r.text.includes(q)).map(({r,i})=>`<div class="reminder-row"><button class="check ${r.done?'checked':''}" onclick="reminders[${i}].done=!reminders[${i}].done;searchReminders('${escapeHTML(q)}')" aria-label="完成${escapeHTML(r.text)}">${r.done?'✓':''}</button><span>${escapeHTML(r.text)}</span></div>`).join(''):''}

function newReminder(){setView(page(header('新提醒事项',`<button class="text-action" onclick="saveReminder()">完成</button>`,'renderReminders()')+`<input class="searchbar" id="reminder-text" placeholder="提醒内容" aria-label="提醒内容">`))}
function saveReminder(){let v=$('#reminder-text').value.trim();if(v)reminders.push({text:v,type:'我的待办',done:false});renderReminders()}
function renderWeather(){setView(page(header('天气')+`<div class="scroll"><div class="weather-hero"><h2>首尔</h2><div class="temperature">18°</div><p>晴朗</p><p>最高22° 最低12°</p><small>界面演示数据 · 非实时天气</small></div><div class="weather-box"><p class="muted">逐小时预报 · 演示</p><div class="hourly">${['现在','10时','11时','12时','13时'].map((x,i)=>`<div>${x}<span>${i<3?'☀':'☁'}</span>${18+i}°</div>`).join('')}</div></div><div class="weather-box"><p class="muted">未来天气 · 演示</p>${['今天','明天','周四','周五','周六'].map((d,i)=>`<div class="forecast-row"><span>${d}</span><span>${i%2?'☁':'☀'}</span><span>${12+i}° ━━━ ${22-i}°</span></div>`).join('')}</div></div>`,'weather-page'),true)}
const places=[['弘大商圈','逛一逛，慢慢走。'],['延南洞咖啡街','找一处可以坐下的地方。'],['京义线森林公园','留一点时间散步。'],['汉江公园','等到傍晚。']];let mapSelected=-1;
function renderMap(){setView(page(header('地图')+`<div class="scroll"><div class="map-canvas"><svg viewBox="0 0 380 300" aria-label="首尔示意地图"><defs><pattern id="blocks" width="55" height="46" patternTransform="rotate(-23)" patternUnits="userSpaceOnUse"><rect width="51" height="42" fill="#e4e4dc" stroke="#fff" stroke-width="5"/></pattern></defs><rect width="380" height="300" fill="url(#blocks)"/><path d="M-30 265Q90 180 175 235T410 190" stroke="#acd4e4" stroke-width="48" fill="none"/><path d="M0 90 380 130M110 0 210 300" stroke="#fff" stroke-width="14"/><path d="M0 90 380 130" stroke="#f6dba2" stroke-width="5"/><path d="M260 0 230 90 310 180" stroke="#bdd5aa" stroke-width="27" fill="none"/><text x="60" y="74" font-size="14" fill="#737e6e">延南洞</text><text x="155" y="162" font-size="23" fill="#677267">弘大</text><text x="230" y="258" font-size="15" fill="#5d91a5">汉江</text><circle cx="180" cy="131" r="8" fill="#1689ff" stroke="#fff" stroke-width="4"/>${mapSelected>=0?`<path d="M180 131 240 100" stroke="#1e8cf5" stroke-width="5"/><circle cx="240" cy="100" r="9" fill="#ed6e60"/>`:''}</svg><div class="map-caption">首尔地点示意 · 非实时导航</div></div><div class="map-sheet"><h2 style="margin:0 0 10px">${mapSelected<0?'去哪里见面？':places[mapSelected][0]}</h2><button class="text-action" onclick="mapSelected=Math.floor(Math.random()*places.length);renderMap()">随机看看 ↻</button>${(mapSelected<0?places: [places[mapSelected]]).map(p=>`<button class="place-card" onclick="placeDetail(${places.indexOf(p)})"><b>⌖ ${p[0]}</b><p>${p[1]}</p><span class="text-action">查看地点 ›</span></button>`).join('')}</div></div>`))}
function placeDetail(i){mapSelected=i;setView(page(header(places[i][0],'','renderMap()')+`<div class="panel"><h2>${places[i][0]}</h2><p>${places[i][1]}</p><p class="muted">首尔约会地点卡片。路线、距离及到达时间未接入真实地图。</p><button class="primary" onclick="renderMap()">在示意地图中查看</button></div>`))}
function renderSettings(){setView(page(header('设置')+`<div class="scroll grouped"><h1 class="large-title">设置</h1><div class="rounded-panel"><div class="list-row">${avatar(null)}<div><b>申正焕</b><p>lovewinsall · 模拟手机</p></div></div></div><div class="rounded-panel">${[['airplane','飞行模式'],['wifi','无线局域网'],['bluetooth','蓝牙']].map(([k,l])=>`<div class="setting-row"><span>${l}</span><button class="toggle ${state[k]?'on':''}" role="switch" aria-checked="${state[k]}" aria-label="${l}" onclick="state.${k}=!state.${k};renderSettings()"></button></div>`).join('')}</div><div class="rounded-panel"><button class="setting-row" style="width:100%" onclick="displaySettings()">显示与亮度 <span>›</span></button><button class="setting-row" style="width:100%" onclick="soundSettings()">声音 <span>›</span></button><button class="setting-row" style="width:100%" onclick="aboutPhone()">关于本机 <span>›</span></button></div><p class="muted" style="padding:0 20px">开关仅影响模拟界面，不会更改真实设备设置。</p></div>`))}
function displaySettings(){setView(page(header('显示与亮度','','renderSettings()')+`<div class="scroll grouped"><div class="rounded-panel">${[['dark','深色外观'],['bold','粗体文本'],['large','放大文字']].map(([k,l])=>`<div class="setting-row"><span>${l}</span><button role="switch" aria-checked="${state[k]}" aria-label="${l}" class="toggle ${state[k]?'on':''}" onclick="state.${k}=!state.${k};displaySettings()"></button></div>`).join('')}</div></div>`))}
function soundSettings(){setView(page(header('声音','','renderSettings()')+`<div class="panel"><p>音乐音量</p><input aria-label="音乐音量" type="range" min="0" max="1" step=".01" value="${music.volume}" oninput="music.volume=Number(this.value)"><p class="muted">通话与语音通过当前设备播放。</p></div>`))}
function aboutPhone(){setView(page(header('关于本机','','renderSettings()')+`<div class="list"><div class="list-row">名称：申正焕的手机</div><div class="list-row">网站：lovewinsall</div><div class="list-row">版本：本地预览 v0.7</div><div class="list-row">刷新页面会重新开始。</div></div>`))}
function renderClock(tab='alarm'){clearInterval(stopwatchTimer);setView(page(header('时钟')+`<div class="scroll"><h1 class="large-title">${tab==='alarm'?'闹钟':tab==='world'?'世界时钟':tab==='stopwatch'?'秒表':'计时器'}</h1>${tab==='alarm'?[['07:00','工作日'],['08:30','周末'],['16:50','每天']].map(([t,l],i)=>`<div class="alarm-row"><div><strong>${t}</strong><p class="muted">${l}</p></div><button class="toggle ${state.alarm[i]?'on':''}" role="switch" aria-label="${t}闹钟" aria-checked="${state.alarm[i]}" onclick="state.alarm[${i}]=!state.alarm[${i}];renderClock()"></button></div>`).join(''):tab==='stopwatch'?`<div class="stopwatch" id="stopwatch-value">${stopwatchText()}</div><div class="timer-actions"><button onclick="stopwatchReset()">复位</button><button id="stopwatch-toggle" onclick="stopwatchToggle()">${state.stopwatchStart?'停止':'开始'}</button></div>`:tab==='world'?`<div class="panel"><h2>首尔</h2><p style="font-size:45px" id="seoul-time"></p><p class="muted">韩国标准时间 · UTC+9</p></div>`:`<div class="panel"><label>分钟 <input type="number" min="1" max="120" value="5" id="timer-minutes" style="width:80px;padding:8px"></label><p id="timer-value" style="font-size:45px">05:00</p><button class="primary" onclick="startCountdown()">开始</button><button onclick="cancelCountdown()" style="padding:12px">取消</button></div>`}</div>`+tabs([['world','世界时钟','clock'],['alarm','闹钟','bell'],['stopwatch','秒表','clock'],['timer','计时器','clock']],tab,'renderClock'),'clock-page'),true);if(tab==='stopwatch')stopwatchTimer=setInterval(()=>{if($('#stopwatch-value'))$('#stopwatch-value').textContent=stopwatchText()},50);if(tab==='world'){$('#seoul-time').textContent=new Date().toLocaleTimeString('zh-CN',{timeZone:'Asia/Seoul',hour:'2-digit',minute:'2-digit'})}}
function stopwatchText(){let ms=state.stopwatchElapsed+(state.stopwatchStart?Date.now()-state.stopwatchStart:0);return formatTime(ms/1000)+'.'+String(Math.floor(ms%1000/10)).padStart(2,'0')}
function stopwatchToggle(){if(state.stopwatchStart){state.stopwatchElapsed+=Date.now()-state.stopwatchStart;state.stopwatchStart=0}else state.stopwatchStart=Date.now();$('#stopwatch-toggle').textContent=state.stopwatchStart?'停止':'开始'}
function stopwatchReset(){state.stopwatchElapsed=0;state.stopwatchStart=0;$('#stopwatch-toggle').textContent='开始';$('#stopwatch-value').textContent=stopwatchText()}
let countdownTimer;function startCountdown(){clearInterval(countdownTimer);let val=Number($('#timer-minutes').value);if(val<1||val>120)return toast('请输入1至120分钟');let end=Date.now()+val*60000;countdownTimer=setInterval(()=>{let sec=Math.max(0,(end-Date.now())/1000);if($('#timer-value'))$('#timer-value').textContent=formatTime(sec);if(sec===0){clearInterval(countdownTimer);toast('计时结束')}},500);toast('计时已开始')}
function cancelCountdown(){clearInterval(countdownTimer);if($('#timer-value'))$('#timer-value').textContent='00:00'}
function renderInbox(id){setView(page(header(appNames[id])+`<h1 class="large-title">${id==='mail'?'收件箱':'信息'}</h1><div class="empty-state">暂无${id==='mail'?'邮件':'短信'}<br><small>聊天内容请打开KakaoTalk查看。</small></div>${id==='messages'?'<button class="primary" style="margin:20px" onclick="openApp(\'kakao\')">打开KakaoTalk</button>':''}`))}
function renderBrowser(){setView(page(header('浏览器')+`<input class="searchbar" value="lovewinsall · 本地阅读列表" readonly aria-label="模拟浏览器地址栏"><div class="scroll"><div class="list"><h2>阅读列表</h2>${places.map((p,i)=>`<button class="list-row" onclick="placeDetail(${i})"><span class="grow"><strong>${p[0]}</strong><p>首尔地点卡片</p></span>›</button>`).join('')}</div><p class="muted" style="padding:20px">此处为手机内的模拟浏览器。</p></div>`))}
function renderCamera(){setView(page(header('相机')+`<div class="camera-view"><div>${icon('camera')}<p>模拟相机</p><p>已提供的照片可在相册中查看</p><p class="muted">本预览不调用设备摄像头</p></div></div><button class="shutter" aria-label="模拟快门" onclick="toast('这是模拟相机，不拍摄真实照片')"></button><button class="text-action" style="padding:15px" onclick="openApp('photos')">打开照片</button>`,'clock-page'),true)}
function renderStore(){setView(page(header('App Store')+`<h1 class="large-title">已安装</h1><div class="scroll list">${['instagram','kakao','x','music'].map(id=>`<div class="list-row"><span class="grow"><b>${appNames[id]}</b><p>模拟手机应用</p></span><button class="primary" onclick="openApp('${id}')">打开</button></div>`).join('')}</div>`))}
renderLock();

function fitPhone(){document.documentElement.style.setProperty('--phone-scale',Math.min(1,(innerHeight-24)/844,(innerWidth-24)/390))}addEventListener('resize',fitPhone);fitPhone();
